package com.aiep.aihub.application.hr;
import com.aiep.aihub.api.hr.HrActor;
import com.aiep.aihub.api.hr.HrCandidateContracts.Run;
import com.aiep.aihub.repository.hr.*;
import com.fasterxml.jackson.databind.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
/** 显式新岗位匹配创建独立计划；同业务输入跨幂等键重用既有终态，不复活旧上传预算。 */
@Service
public class HrMatchingExecutionPlans {
 public record Plan(String runId,String scope,String budgetRef,String planRef,Instant deadline,int maximumAttempts,int maximumCalls,long maxCost,boolean cpuOnly){}
 private final HrMatchingExecutionPlanMapper mapper;private final HrMatchingRepository runs;private final HrBatchMapper policies;private final HrSemanticGateway gateway;private final ObjectMapper json;
 public HrMatchingExecutionPlans(HrMatchingExecutionPlanMapper mapper,HrMatchingRepository runs,HrBatchMapper policies,HrSemanticGateway gateway,ObjectMapper json){this.mapper=mapper;this.runs=runs;this.policies=policies;this.gateway=gateway;this.json=json;}
 public String scope(HrActor actor,String candidateId,String factSnapshotId,String positionId,String configVersionHash,String contextVersion,LocalDate asOfDate){HrAccessPolicy.require(actor,"hr:matching:run");if(candidateId==null||factSnapshotId==null||positionId==null||configVersionHash==null||contextVersion==null||asOfDate==null)throw HrPositionService.invalid("匹配执行快照不完整");return "hr-match-"+UUID.nameUUIDFromBytes(HrPositionService.hash(List.of(actor.tenantId(),candidateId,factSnapshotId,positionId,configVersionHash,contextVersion,asOfDate)).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 public Run findRun(HrActor actor,String scope){Plan plan=find(actor,scope);return plan==null?null:runs.run(actor.tenantId(),plan.runId());}
 public Plan find(HrActor actor,String scope){HrAccessPolicy.require(actor,"hr:matching:run");validateScope(scope);var row=mapper.find(actor.tenantId(),scope);if(row==null)return null;try{Plan plan=json.readValue(row.payload(),Plan.class);if(!scope.equals(plan.scope())||!row.runId().equals(plan.runId()))throw new IllegalStateException("HR_MATCH_PLAN_INVALID");return plan;}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("HR_MATCH_PLAN_INVALID");}}
 public Plan prepare(HrActor actor,String runId,String scope,int semanticBatches,boolean explainNeeded){HrAccessPolicy.require(actor,"hr:matching:run");validateScope(scope);if(runId==null||runId.isBlank()||runId.length()>64||semanticBatches<0||semanticBatches>4)throw HrPositionService.invalid("匹配工作量无效");Plan existing=find(actor,scope);if(existing!=null)return existing;int operations=semanticBatches+(explainNeeded?1:0);boolean cpu=operations==0;int attempts=3;var policy=policies.latestPolicy(actor.tenantId());if(policy!=null){try{JsonNode configured=json.readTree(policy.payload());if(!configured.path("maximumAttempts").isIntegralNumber())throw new HrBusinessException("HR_POLICY_NOT_READY","新任务缺少有效模型尝试上限",409);attempts=configured.path("maximumAttempts").asInt();}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("HR_POLICY_INVALID");}}else if(!cpu)throw new HrBusinessException("HR_POLICY_NOT_READY","请先确认招聘材料使用政策",409);if(attempts<1||attempts>3)throw HrPositionService.invalid("模型尝试上限无效");String budgetRef="CPU_ONLY",planRef=HrPositionService.hash(List.of(actor.tenantId(),scope,"CPU_ONLY"));Instant deadline=Instant.now().plusSeconds(600);int calls=0;long cost=0;if(!cpu){var input=json.createObjectNode().put("maximum_attempts",attempts);var workload=input.putArray("workload");for(int index=0;index<semanticBatches;index++)workload.addObject().put("run_ref",scope).put("skill_key","hr.requirements.evaluate").put("attempts",attempts);if(explainNeeded)workload.addObject().put("run_ref",scope).put("skill_key","hr.match.explain").put("attempts",attempts);JsonNode checked=gateway.execute(actor,6109,"hr-match-plan-"+HrPositionService.hash(scope).substring(0,32),input);budgetRef=checked.path("budget_ref").asText();planRef=checked.path("plan_ref").asText();if(!checked.path("ready").asBoolean()||budgetRef.isBlank()||!planRef.matches("[0-9a-f]{64}")||!checked.path("deadline_epoch_ms").isIntegralNumber()||!checked.path("maximum_calls").isIntegralNumber())throw new HrBusinessException("HR_MATCH_BUDGET_REQUIRED","新匹配任务预算未就绪",409);deadline=Instant.ofEpochMilli(checked.path("deadline_epoch_ms").asLong());calls=checked.path("maximum_calls").asInt();cost=checked.path("maximum_cost_microunits").asLong();if(calls<operations||calls>operations*attempts||calls%operations!=0||!deadline.isAfter(Instant.now()))throw new HrBusinessException("HR_MATCH_PLAN_INVALID","工作量或预算截止已失效",409);attempts=calls/operations;}
 Plan plan=new Plan(runId,scope,budgetRef,planRef,deadline,attempts,calls,cost,cpu);try{mapper.insert(new HrMatchingExecutionPlanMapper.Row(actor.tenantId(),scope,runId,json.writeValueAsString(plan)));return plan;}catch(org.springframework.dao.DuplicateKeyException race){Plan winner=find(actor,scope);if(winner==null)throw HrPositionService.conflict();return winner;}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("HR_MATCH_PLAN_INVALID");}}
 private static void validateScope(String scope){if(scope==null||!scope.matches("hr-match-[A-Za-z0-9-]{1,64}"))throw HrPositionService.invalid("匹配业务scope无效");}
}
